mapper.select:
select m.menu_id
from `ry_rental`.`ry_rental_merchant_menu` m
    inner join `ry_rental`.`ry_rental_merchant_user_menu` um
        on m.menu_id = um.menu_id
where um.tenant_id = #{tenantId}
  and um.member_id = #{memberId}
  and um.merchant_user_id = #{merchantUserId}
  and m.tenant_id = 0
  and m.member_id = 0
  and m.del_flag = '0'

      and m.menu_id not in (
          select cm.parent_id
          from `ry_rental`.`ry_rental_merchant_menu` cm
              inner join `ry_rental`.`ry_rental_merchant_user_menu` cum
                  on cm.menu_id = cum.menu_id
          where cum.tenant_id = #{tenantId}
            and cum.member_id = #{memberId}
            and cum.merchant_user_id = #{merchantUserId}
            and cm.tenant_id = 0
            and cm.member_id = 0
            and cm.del_flag = '0'
      )

order by m.parent_id, m.order_num

mapper.delete:
delete from `ry_rental`.`ry_rental_merchant_user_menu`
where tenant_id = #{tenantId}
  and member_id = #{memberId}
  and merchant_user_id in

    #{merchantUserId}
